metadata.er-schema:
{
  "title": "looply · 社媒分享 实体关系图",
  "version": "v1.0 · 2026-06-03",
  "tables": [
    {
      "name": "short_links",
      "comment": "短链主表",
      "columns": [
        {
          "name": "short_code",
          "comment": "短码（URL路径）",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "long_url",
          "comment": "完整目标URL",
          "constraint": ""
        },
        {
          "name": "link_type",
          "comment": "链接类型",
          "constraint": ""
        },
        {
          "name": "utm_source",
          "comment": "渠道平台",
          "constraint": ""
        },
        {
          "name": "utm_medium",
          "comment": "营销类型",
          "constraint": ""
        },
        {
          "name": "utm_campaign",
          "comment": "活动类型",
          "constraint": ""
        },
        {
          "name": "utm_content",
          "comment": "分享入口/账号",
          "constraint": ""
        },
        {
          "name": "share_id",
          "comment": "分享事件ID",
          "constraint": "UNIQUE"
        },
        {
          "name": "product_id",
          "comment": "商品ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "sharer_user_id",
          "comment": "分享人用户ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "session_id",
          "comment": "匿名session",
          "constraint": ""
        },
        {
          "name": "created_by",
          "comment": "运营创建人",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "campaign_name",
          "comment": "运营备注名称",
          "constraint": ""
        },
        {
          "name": "click_count",
          "comment": "点击计数",
          "constraint": ""
        },
        {
          "name": "unique_visitor_count",
          "comment": "独立访客数",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        }
      ],
      "note": "统一承载用户分享 + 运营投放两种短链"
    },
    {
      "name": "share_clicks",
      "comment": "点击记录表",
      "columns": [
        {
          "name": "id",
          "comment": "自增主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "share_id",
          "comment": "关联短链",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "visitor_id",
          "comment": "匿名访客ID",
          "constraint": ""
        },
        {
          "name": "user_id",
          "comment": "登录用户ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "clicked_at",
          "comment": "点击时间",
          "constraint": ""
        },
        {
          "name": "ip",
          "comment": "IP地址",
          "constraint": ""
        },
        {
          "name": "user_agent",
          "comment": "浏览器UA",
          "constraint": ""
        },
        {
          "name": "referer",
          "comment": "来源页面",
          "constraint": ""
        }
      ],
      "note": ""
    },
    {
      "name": "share_attributions",
      "comment": "转化归因表",
      "columns": [
        {
          "name": "id",
          "comment": "自增主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "share_id",
          "comment": "关联短链",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "user_id",
          "comment": "转化用户ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "event_type",
          "comment": "转化事件类型",
          "constraint": ""
        },
        {
          "name": "order_id",
          "comment": "订单ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "gmv_cents",
          "comment": "GMV（美分）",
          "constraint": ""
        },
        {
          "name": "attributed_at",
          "comment": "归因时间",
          "constraint": ""
        }
      ],
      "note": ""
    },
    {
      "name": "products",
      "comment": "商品（外部）",
      "columns": [
        {
          "name": "product_id",
          "comment": "商品ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "title",
          "comment": "商品标题",
          "constraint": ""
        },
        {
          "name": "brand",
          "comment": "品牌",
          "constraint": ""
        },
        {
          "name": "price_cents",
          "comment": "价格",
          "constraint": ""
        },
        {
          "name": "image_url",
          "comment": "主图URL",
          "constraint": ""
        }
      ],
      "note": "商品模块提供，本模块只读"
    },
    {
      "name": "users",
      "comment": "用户（外部）",
      "columns": [
        {
          "name": "user_id",
          "comment": "用户ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "username",
          "comment": "用户名",
          "constraint": ""
        }
      ],
      "note": "用户模块提供，本模块只读"
    },
    {
      "name": "orders",
      "comment": "订单（外部）",
      "columns": [
        {
          "name": "order_id",
          "comment": "订单ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "user_id",
          "comment": "下单用户",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "total_cents",
          "comment": "订单金额",
          "constraint": ""
        }
      ],
      "note": "订单模块提供，本模块只读"
    }
  ],
  "relations": [
    {
      "from": "short_links",
      "to": "share_clicks",
      "type": "1:N",
      "label": "被点击",
      "color": "#1565C0",
      "penwidth": 1.8
    },
    {
      "from": "short_links",
      "to": "share_attributions",
      "type": "1:N",
      "label": "带来转化",
      "color": "#1565C0",
      "penwidth": 1.8
    },
    {
      "from": "short_links",
      "to": "products",
      "type": "N:1",
      "label": "分享商品",
      "color": "#90CAF9"
    },
    {
      "from": "short_links",
      "to": "users",
      "type": "N:1",
      "label": "分享人",
      "color": "#90CAF9"
    },
    {
      "from": "share_clicks",
      "to": "users",
      "type": "N:1",
      "label": "点击者",
      "color": "#90CAF9",
      "style": "dashed"
    },
    {
      "from": "share_attributions",
      "to": "users",
      "type": "N:1",
      "label": "转化用户",
      "color": "#F4A460"
    },
    {
      "from": "share_attributions",
      "to": "orders",
      "type": "N:1",
      "label": "归因订单",
      "color": "#F4A460"
    }
  ],
  "design_rules": {
    "link_type_enum": "link_type 枚举值：user_share（用户分享）/ marketing（运营投放）",
    "status_enum": "status 枚举值：active / disabled / expired",
    "event_type_enum": "event_type 枚举值：signup / first_order / repeat_order",
    "attribution_window": "归因窗口：点击→注册 7天，点击→下单 30天，多次点击取 Last Click",
    "cookie_ttl": "Cookie _looply_ref 有效期 30 天，_looply_vid 持久化",
    "short_code_format": "用户分享：sh_ + 6-8位Base62；运营创建：6-8位Base62",
    "utm_medium_filter": "GA4 筛选 utm_medium=social_share 可分离用户分享流量",
    "og_strategy": "MVP 阶段 OG 数据实时关联查 products 表，不冗余存储"
  }
}
